import{_ as n,a0 as r,w as o,s as u,ao as p,I as s,a1 as l,A as e,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Dialect：Linux 下的开源翻译应用 | LCTT x X-CMD","titleTemplate":false,"description":"Dialect：Linux 下的开源翻译应用 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Dialect：Linux 下的开源翻译应用 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Dialect：Linux 下的开源翻译应用 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20210929 Dialect- An Open-Source Translation App for Linux","title":"Dialect：Linux 下的开源翻译应用","tag":"202110","desc":""},"relativePath":"202110/20210929 Dialect- An Open-Source Translation App for Linux.md","filePath":"[post].md"}'),d={name:"202110/20210929 Dialect- An Open-Source Translation App for Linux.md"};function f(m,t,g,b,h,x){const a=r("Link");return o(),u("div",null,[t[24]||(t[24]=p('<h1 id="dialect-linux-下的开源翻译应用" tabindex="-1">Dialect：Linux 下的开源翻译应用 <a class="header-anchor" href="#dialect-linux-下的开源翻译应用" aria-label="Permalink to “Dialect：Linux 下的开源翻译应用”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202110/10/115724t5xgx8agu8asag0u.jpg" alt=""></p><blockquote><p>Dialect 是一个简单明了的应用，可以让你使用 Web 服务进行语言间的翻译。想要了解更多的话，让我们来一窥究竟。</p></blockquote><p>虽然你可以启动 Web 浏览器并直接使用任何翻译服务来完成工作，但桌面应用有时会派上用场。</p><p>Dialect 是一个简单的翻译应用，可以利用 Web 服务进行翻译，同时给你一些额外的能力。</p><h3 id="使用谷歌翻译和-libretranslate-的开源翻译应用" tabindex="-1">使用谷歌翻译和 LibreTranslate 的开源翻译应用 <a class="header-anchor" href="#使用谷歌翻译和-libretranslate-的开源翻译应用" aria-label="Permalink to “使用谷歌翻译和 LibreTranslate 的开源翻译应用”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-screenshot.png?resize=800%2C331&amp;ssl=1" alt=""></p><p>Dialect 是一个主要为 GNOME 桌面定制的应用，但它在其他桌面环境下也应该能正常工作。</p><p>它可以让你快速翻译语言，同时还有一些额外的选项。</p><p>在其核心部分，你可以选择谷歌翻译或 LibreTranslate 翻译服务。</p><p>尽管 LibreTranslate 达不到谷歌翻译的准确性，但把它作为一个选项来切换是一个很好的补充。至少，对于一些基本的用法，如果用户不想利用谷歌的服务，你的桌面上就有一个备选方案。</p><h3 id="dialect-的特点" tabindex="-1">Dialect 的特点 <a class="header-anchor" href="#dialect-的特点" aria-label="Permalink to “Dialect 的特点”">​</a></h3><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-app-options.png?resize=800%2C470&amp;ssl=1" alt=""></p><p>除了切换翻译服务外，你还能得到如下个功能：</p><ul><li>发音</li><li>文本到语音（TTS）功能（谷歌）</li><li>黑暗模式</li><li>翻译快捷方式</li><li>实时翻译</li><li>剪贴板按钮可快速复制/粘贴</li><li>翻译历史（撤销/重做）</li></ul><p>正如你在截图中所注意到的，实时翻译功能可能会因为滥用 API 而使你的 IP 地址被禁止使用服务。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/09/dialect-libretranslate.png?resize=800%2C326&amp;ssl=1" alt=""></p><p>我试着使用 LibreTranslate（如上图所示）和谷歌翻译，并启用实时翻译功能，它工作得很好。</p><p>也许，如果你经常依赖翻译，你可能想避免这个实时翻译。但是，对于我的临时使用，在相当多的测试中，该服务并没有导致 IP 地址被禁止。</p><p>重要的是要注意，如果你想，你可以指定一个自定义的 LibreTranslate 实例。默认情况下，它使用 “translate.astian.org” 作为实例。</p><p>你可能找不到一个单独显示的翻译历史区域，但窗口左上角的箭头按钮会让你看到你以前的翻译，以及翻译设置。</p><p>所以，它也可以作为一个重做/撤销的功能。</p><h3 id="在-linux-中安装-dialect" tabindex="-1">在 Linux 中安装 Dialect <a class="header-anchor" href="#在-linux-中安装-dialect" aria-label="Permalink to “在 Linux 中安装 Dialect”">​</a></h3>',23)),s("p",null,[l(a,{href:"https://flathub.org/apps/details/com.github.gi_lom.dialect"},{default:e(()=>[...t[0]||(t[0]=[i("Dialect",-1)])]),_:1}),t[3]||(t[3]=i(" 是以 ",-1)),l(a,{href:"https://itsfoss.com/what-is-flatpak/"},{default:e(()=>[...t[1]||(t[1]=[i("Flatpak",-1)])]),_:1}),t[4]||(t[4]=i(" 的形式提供的。所以，你应该能够在你选择的任何 Linux 发行版上安装它。如果你是新手，你可能想看看我们的 ",-1)),l(a,{href:"https://itsfoss.com/flatpak-guide/"},{default:e(()=>[...t[2]||(t[2]=[i("Flatpak 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 以获得帮助。",-1))]),t[25]||(t[25]=p('<p>首先，添加 Flathub 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span></code></pre></div><p>然后安装应用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.github.gi_lom.dialect</span></span></code></pre></div><p>安装后，在系统菜单中寻找它，并从那里启动它。</p>',5)),s("p",null,[t[7]||(t[7]=i("你也可以浏览它的 ",-1)),l(a,{href:"https://github.com/dialect-app/dialect/"},{default:e(()=>[...t[6]||(t[6]=[i("GitHub 页面",-1)])]),_:1}),t[8]||(t[8]=i(" 了解更多信息。",-1))]),t[26]||(t[26]=s("hr",null,null,-1)),s("p",null,[t[10]||(t[10]=i("via: ",-1)),l(a,{href:"https://itsfoss.com/dialect/"},{default:e(()=>[...t[9]||(t[9]=[i("https://itsfoss.com/dialect/",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=i("作者：",-1)),l(a,{href:"https://itsfoss.com/author/ankush/"},{default:e(()=>[...t[11]||(t[11]=[i("Ankush Das",-1)])]),_:1}),t[16]||(t[16]=i(" 选题：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[12]||(t[12]=[i("lujun9972",-1)])]),_:1}),t[17]||(t[17]=i(" 译者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:e(()=>[...t[13]||(t[13]=[i("geekpi",-1)])]),_:1}),t[18]||(t[18]=i(" 校对：",-1)),l(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=i("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原创编译，",-1)),l(a,{href:"https://linux.cn/"},{default:e(()=>[...t[20]||(t[20]=[i("Linux中国",-1)])]),_:1}),t[23]||(t[23]=i(" 荣誉推出",-1))])])}const D=n(d,[["render",f]]);export{L as __pageData,D as default};
